def f(g):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    from collections import defaultdict
    col=defaultdict(list)
    for i in range(h):
        for j in range(w):
            if g[i][j]: col[g[i][j]].append((i,j))
    for c,pts in col.items():
        if len(pts)==1:
            i,j=pts[0]
            for k in range(h):
                if out[k][j]==0: out[k][j]=c
        else:
            (i1,j1),(i2,j2)=pts
            for k in range(min(i1,i2),max(i1,i2)+1):
                if out[k][j1]==0: out[k][j1]=c
            for k in range(min(j1,j2),max(j1,j2)+1):
                if out[i2][k]==0: out[i2][k]=c
    return out
